import com.edu.scnu.domain.runtime.RecordData
import com.edu.scnu.domain.shared.DomainException

def changes = new RecordData(args.values)
def current = args.create ? null : row
def cap = changes.containsKey('capacity') ? changes.getInt('capacity') : current?.getInt('capacity')
if (cap == null || cap <= 0) {
    throw DomainException.invalidParams('货架容量上限必须为正整数（>= 1）')
}
def nextStatus = changes.containsKey('status') ? changes.getStr('status') : (current?.getStr('status') ?: 'ENABLED')
if (!args.create && current != null) {
    def scope = env.getDataScope()
    int activeCnt = 0
    try {
        env.setDataScope('ALL')
        def c = env.get('exp_parcel').call('count', [filter: [['shelf_id', '=', current.getId()], ['status', 'in', ['PENDING', 'READY', 'PROBLEM']]]])
        activeCnt = (c instanceof Number) ? c.intValue() : 0
    } finally {
        env.setDataScope(scope)
    }
    if (cap < activeCnt) {
        throw DomainException.stateGuardFailed("容量上限 (" + cap + ") 不能小于当前在架包裹数 (" + activeCnt + " 件)")
    }
    if (nextStatus == 'DISABLED' && activeCnt > 0 && !args.serviceWrite) {
        throw DomainException.stateGuardFailed("该货架尚存 " + activeCnt + " 件未出库包裹，请先移库或出库后再停用维护")
    }
}
return true

import com.edu.scnu.domain.shared.DomainException

if (row) {
    def scope = env.getDataScope()
    int activeCnt = 0
    try {
        env.setDataScope('ALL')
        def c = env.get('exp_parcel').call('count', [filter: [['shelf_id', '=', row.getId()], ['status', 'in', ['PENDING', 'READY', 'PROBLEM']]]])
        activeCnt = (c instanceof Number) ? c.intValue() : 0
    } finally {
        env.setDataScope(scope)
    }
    if (activeCnt > 0) {
        throw DomainException.stateGuardFailed("货架 [" + (row.getStr('shelf_code')) + "] 尚有 " + activeCnt + " 件在架包裹，禁止删除")
    }
}
return true

import com.edu.scnu.domain.shared.DomainException

if (!row) throw DomainException.invalidParams('货架记录不存在')
if (row.getStr('status') != 'ENABLED') {
    throw DomainException.stateGuardFailed('只有“正常启用”的货架才能停用维护')
}
def scope = env.getDataScope()
int activeCnt = 0
try {
    env.setDataScope('ALL')
    def c = env.get('exp_parcel').call('count', [filter: [['shelf_id', '=', row.getId()], ['status', 'in', ['PENDING', 'READY', 'PROBLEM']]]])
    activeCnt = (c instanceof Number) ? c.intValue() : 0
} finally {
    env.setDataScope(scope)
}
if (activeCnt > 0) {
    throw DomainException.stateGuardFailed("货架 [" + (row.getStr('shelf_code')) + "] 尚有 " + activeCnt + " 件未出库包裹，请先移库或取件出库后再停用维护！")
}
return rs.updateFromService([id: row.getId(), version: row.getInt('version'), values: [status: 'DISABLED']])

import com.edu.scnu.domain.shared.DomainException

if (!row) throw DomainException.invalidParams('签收批次不存在')
if (row.getStr('status') != 'ARRIVED') {
    throw DomainException.stateGuardFailed('该批次已完成清点！')
}
int createdParcels = 0
def scope = env.getDataScope()
try {
    env.setDataScope('ALL')
    def detailRs = env.get('exp_inbound_detail')
    def parcelRs = env.get('exp_parcel')
    def details = detailRs.call('search', [filter: [['batch_id', '=', row.getId()]], limit: 500]).records ?: []
    def brand = row.getStr('courier_brand') ?: 'SF'
    for (def d : details) {
        if (d.getBool('damaged')) continue
        def tno = d.getStr('tracking_no')?.trim()
        def rname = d.getStr('recipient_name')?.trim()
        def rphone = d.getStr('recipient_phone')?.trim()
        if (!tno || !rname || !rphone || !(rphone ==~ /^1\d{10}$/)) continue
        boolean exists = parcelRs.call('exists', [filter: [['tracking_no', '=', tno]]])
        if (!exists) {
            parcelRs.createFromService([values: [
                tracking_no: tno,
                courier_brand: brand,
                parcel_size: d.getStr('parcel_size') ?: 'SMALL',
                recipient_name: rname,
                recipient_phone: rphone,
                status: 'PENDING',
                remark: d.getStr('note') ?: ('随车批次 ' + (row.getStr('batch_no') ?: '') + ' 自动清点入库')
            ]])
            createdParcels++
        }
    }
} finally {
    env.setDataScope(scope)
}
rs.updateFromService([id: row.getId(), version: row.getInt('version'), values: [status: 'CHECKED']])
if (createdParcels > 0) {
    return JsonRpcServiceResponse.reloadWindow("批次清点完成！已同步生成 " + createdParcels + " 件待上架包裹入库单")
}
return JsonRpcServiceResponse.reloadWindow('到站批次清点完成！')

import com.edu.scnu.domain.runtime.RecordData
import com.edu.scnu.domain.shared.DomainException

def changes = new RecordData(args.values)
def current = args.create ? null : row
def curStatus = current?.getStr('status')
def nextStatus = changes.containsKey('status') ? changes.getStr('status') : (curStatus ?: 'PENDING')
def nextCode = (changes.containsKey('pickup_code') ? changes.getStr('pickup_code') : current?.getStr('pickup_code'))?.toString()?.trim()
if (nextCode == '') nextCode = null
def targetShelfId = changes.containsKey('shelf_id') ? changes.getStr('shelf_id') : current?.getStr('shelf_id')

def effectiveStatuses = ['PENDING', 'READY', 'PROBLEM']
if (!args.serviceWrite) {
    if (!args.create && (curStatus == 'PICKED' || curStatus == 'RETURNED')) {
        throw DomainException.stateGuardFailed("包裹已出库（" + (curStatus == 'PICKED' ? '已取走' : '已退回') + "），不能修改信息或重复出库！")
    }
    if (changes.containsKey('status') && nextStatus != curStatus && (nextStatus == 'PICKED' || nextStatus == 'RETURNED')) {
        throw DomainException.stateGuardFailed('请使用「核验取件出库」或「退回寄件人」操作办理出库')
    }
    if (changes.containsKey('status') && args.create && nextStatus != 'PENDING' && nextStatus != 'READY') {
        throw DomainException.stateGuardFailed('新入库包裹初始状态只能为待上架或待取件')
    }
}

if ((nextStatus == 'READY' || nextStatus == 'PROBLEM') && !nextCode) {
    throw DomainException.invalidParams('待取件或异常滞留状态必须具备有效取件码')
}

def scope = env.getDataScope()
try {
    env.setDataScope('ALL')
    // 禁止同一驿站下出现重复有效的取件码（PENDING/READY/PROBLEM 视为有效未出库状态）
    if (nextCode && (nextStatus in effectiveStatuses)) {
        def codeFilter = [['pickup_code', '=', nextCode], ['status', 'in', effectiveStatuses]]
        if (!args.create && current != null) {
            codeFilter << ['id', '!=', current.getId()]
        }
        if (rs.call('exists', [filter: codeFilter])) {
            throw DomainException.invalidParams("取件码 [" + nextCode + "] 已被当前在库有效包裹占用，不能出现重复有效的取件码！")
        }
    }
    // 校验目标货架启用状态与容量余量
    if (targetShelfId && (nextStatus in effectiveStatuses)
            && (args.create || changes.containsKey('shelf_id') || changes.containsKey('status'))) {
        def shelf = env.get('exp_shelf').call('find', [id: targetShelfId])
        if (shelf.getStr('status') != 'ENABLED') {
            throw DomainException.stateGuardFailed("货架 [" + (shelf.getStr('shelf_code')) + "] 当前已停用维护，不可存放包裹！")
        }
        int cap = shelf.getInt('capacity') ?: 0
        def shelfFilter = [['shelf_id', '=', targetShelfId], ['status', 'in', effectiveStatuses]]
        if (!args.create && current != null) {
            shelfFilter << ['id', '!=', current.getId()]
        }
        def activeCount = env.get('exp_parcel').call('count', [filter: shelfFilter])
        int used = (activeCount instanceof Number) ? activeCount.intValue() : 0
        if (cap > 0 && used >= cap) {
            throw DomainException.stateGuardFailed("货架 [" + (shelf.getStr('shelf_code')) + "] 已满（容量上限 " + cap + " 件），请更换其他货架！")
        }
    }
} finally {
    env.setDataScope(scope)
}
return true

import com.edu.scnu.domain.shared.DomainException

if (!row) throw DomainException.invalidParams('包裹记录不存在')
if (row.getStr('status') != 'PENDING') {
    throw DomainException.stateGuardFailed('只有“待上架”状态的包裹才能执行上架操作！')
}
def targetShelfId = args.shelf_id?.toString()?.trim() ?: row.getStr('shelf_id')
if (!targetShelfId) {
    throw DomainException.invalidParams('请先选择要存放的目标货架！')
}

def scope = env.getDataScope()
String finalCode = row.getStr('pickup_code')?.trim()
String shelfCode = ''
try {
    env.setDataScope('ALL')
    def shelf = env.get('exp_shelf').call('find', [id: targetShelfId])
    shelfCode = shelf.getStr('shelf_code') ?: targetShelfId
    if (shelf.getStr('status') != 'ENABLED') {
        throw DomainException.stateGuardFailed("货架 [" + shelfCode + "] 当前已停用维护，不可上架！")
    }
    int cap = shelf.getInt('capacity') ?: 0
    def effectiveStatuses = ['PENDING', 'READY', 'PROBLEM']
    def usedNum = rs.call('count', [filter: [['shelf_id', '=', targetShelfId], ['status', 'in', effectiveStatuses], ['id', '!=', row.getId()]]])
    int used = (usedNum instanceof Number) ? usedNum.intValue() : 0
    if (cap > 0 && used >= cap) {
        throw DomainException.stateGuardFailed("货架 [" + shelfCode + "] 容量已满（上限 " + cap + " 件），请选择其他货架！")
    }

    if (!finalCode) {
        String zone = (shelf.getStr('zone_type') ?: 'A').trim()
        def digitsMatcher = (shelfCode =~ /\d+/)
        String shelfTag = digitsMatcher.find() ? digitsMatcher.group(0) : '1'
        int startSeq = used + 1
        for (int i = 0; i < 5000; i++) {
            int seq = ((startSeq + i - 1) % 9999) + 1
            String candidate = String.format('%s-%s-%03d', zone, shelfTag, seq)
            boolean taken = rs.call('exists', [filter: [['pickup_code', '=', candidate], ['status', 'in', effectiveStatuses], ['id', '!=', row.getId()]]])
            if (!taken) {
                finalCode = candidate
                break
            }
        }
        if (!finalCode) {
            throw DomainException.stateGuardFailed('未能分配到可用的唯一取件码，请稍后重试')
        }
    }
} finally {
    env.setDataScope(scope)
}

rs.updateFromService([id: row.getId(), version: row.getInt('version'), values: [
    shelf_id: targetShelfId,
    pickup_code: finalCode,
    status: 'READY',
    shelved_time: now
]])
return JsonRpcServiceResponse.reloadWindow("上架成功！存放货架 [" + shelfCode + "]，生成取件码：" + finalCode + "")

int d = ((row.storage_days ?: 0) as int);
double fee = d > 3 ? (d - 3) * 1.0d : 0.0d;
rs.updateFromService([id: row.id, version: row.version, values: [overdue_fee: fee]]);
return JsonRpcServiceResponse.message('取件码 [' + (row.pickup_code ?: row.inbound_no) + '] 滞留 ' + d + ' 天，超期保管费：￥' + fee);

import com.edu.scnu.domain.runtime.RecordData
import com.edu.scnu.domain.shared.DomainException

if (args.serviceWrite) return true
if (!args.create) {
    throw DomainException.stateGuardFailed('快递出库台账为不可篡改凭证，禁止修改！')
}
def changes = new RecordData(args.values)
def parcelId = changes.getStr('parcel_id')
def outType = changes.getStr('outbound_type') ?: 'PICKUP'
if (!parcelId) {
    throw DomainException.invalidParams('请选择要办理出库的包裹')
}
if (!(outType in ['PICKUP', 'RETURN'])) {
    throw DomainException.invalidParams('出库类型必须为 PICKUP（取件出库）或 RETURN（退货出库）')
}
def parcelRs = env.get('exp_parcel')
def parcel = parcelRs.call('find', [id: parcelId])
def pStatus = parcel.getStr('status')
if (pStatus == 'PICKED' || pStatus == 'RETURNED') {
    throw DomainException.stateGuardFailed("该包裹已完成出库（" + (pStatus == 'PICKED' ? '已取走' : '已退回') + "），严禁重复出库！")
}
if (outType == 'PICKUP' && pStatus != 'READY') {
    throw DomainException.stateGuardFailed('正常取件出库仅支持“待取件”状态包裹，请先执行上架！')
}
if (outType == 'RETURN' && !(pStatus in ['PENDING', 'READY', 'PROBLEM'])) {
    throw DomainException.stateGuardFailed('当前包裹状态不支持退货出库！')
}

int d = ((parcel.getInt('storage_days') ?: 0) as int)
double fee = (outType == 'PICKUP') ? (d > 3 ? (d - 3) * 1.0d : 0.0d) : (parcel.getDouble('overdue_fee') ?: 0.0d)
String targetStatus = (outType == 'PICKUP') ? 'PICKED' : 'RETURNED'

parcelRs.updateFromService([id: parcelId, version: parcel.getInt('version'), values: [
    status: targetStatus,
    overdue_fee: fee,
    outbound_type: outType,
    outbound_time: now
]])

args.values.put('outbound_type', outType)
args.values.put('tracking_no', parcel.getStr('tracking_no'))
args.values.put('pickup_code', parcel.getStr('pickup_code'))
if (parcel.getStr('shelf_id')) args.values.put('shelf_id', parcel.getStr('shelf_id'))
args.values.put('recipient_name', parcel.getStr('recipient_name'))
args.values.put('recipient_phone', parcel.getStr('recipient_phone'))
args.values.put('overdue_fee', fee)
args.values.put('outbound_time', now)
args.values.put('operator_name', env.getUsername() ?: currentUser)
args.values.put('status', 'COMPLETED')
if (!changes.getStr('reason')?.trim()) {
    args.values.put('reason', outType == 'PICKUP' ? '出库台账直接办理取件出库' : '出库台账办理退货出库')
}
return true
